function costText(cost){return Object.entries(cost).map(([k,v])=>`${{scrap:'🔩',food:'🥫',fuel:'⛽',medicine:'✚'}[k]} ${v}`).join(' · ')}
function render(){
 $('resources').innerHTML=[['🔩','SẮT VỤN','scrap','Vật liệu'],['🥫','LƯƠNG THỰC','food','Dự trữ'],['⛽','NHIÊN LIỆU','fuel','Dầu máy'],['✚','THUỐC MEN','medicine','Y tế'],['♟','CƯ DÂN','people','Sống sót']].map(([i,n,k,sub])=>`<div class="resource"><div class="ricon">${i}</div><div><div class="rlabel">${n}</div><div class="rvalue">${s[k]}${k==='people'?'':' <span style="font-size:10px;color:#859184">'+sub+'</span>'}</div></div></div>`).join('')+`<div class="resource day"><div><div class="daytop">NGÀY ${s.day} / 30</div><div class="daybottom">${s.actions} mệnh lệnh còn lại</div></div><div class="rchange">⌛</div></div>`;
 const waveIn=4-((s.day-1)%4);$('threatText').textContent=waveIn===1?'Đêm nay sẽ có tấn công!':`Tín hiệu nguy hiểm sau ${waveIn} ngày`;
 $('actionsLeft').textContent=`${s.actions} / 2 MỆNH LỆNH CÒN LẠI`;
 $('status').innerHTML=[['TINH THẦN',s.morale,100,s.morale<35],['SỨC MẠNH PHÒNG THỦ',defense(),100,false],['SỨC KHỎE CƯ DÂN',Math.min(100,Math.round(s.people*9+s.morale*.25)),100,s.people<4]].map(([label,val,max,bad])=>`<div class="stat"><div class="statline"><span>${label}</span><strong>${val}${label==='TINH THẦN'?'%':''}</strong></div><div class="meter ${bad?'danger':''}"><i style="width:${Math.min(100,val/max*100)}%"></i></div></div>`).join('');
 const actions=[['scavenge','⌕','LỤC SOÁT KHU VỰC','Thu gom sắt vụn, lương thực hoặc nhiên liệu. Có rủi ro phục kích.','Chọn khu vực →'],['hunt','◉','SĂN THỰC PHẨM','Tìm nguồn thức ăn ngoài hoang địa; có thể gặp nguy hiểm.','1 mệnh lệnh'],['repair','⚒','SỬA CHỮA CĂN CỨ','Dùng 8 sắt vụn để vá lũy, phục hồi phòng thủ.','🔩 8']];
 $('actions').innerHTML=actions.map(([id,icon,name,desc,cost])=>`<button class="action-card" data-action="${id}" ${s.actions<=0||s.gameOver?'disabled':''}><span class="action-icon">${icon}</span><strong>${name}</strong><small>${desc}</small><span class="cost">${cost}</span></button>`).join('');
 $('buildings').innerHTML=builds.map(b=>{let l=s[b.key],cost=Object.fromEntries(Object.entries(b.base).map(([k,v])=>[k,v*l]));return `<div class="builditem"><div class="buildicon">${b.icon}</div><div><div class="buildname">${b.name} · Cấp ${l}</div><div class="builddesc">${b.desc}</div><div class="buildlevel">${b.effect(l)}</div></div><button class="mini-btn" data-build="${b.key}" ${s.actions<=0||!affords(cost)||s.gameOver?'disabled':''}>NÂNG<br>${costText(cost)}</button></div>`}).join('');
 renderMercs();
 const mood=s.morale>=75?'VỮNG VÀNG':s.morale>=50?'ỔN ĐỊNH':s.morale>=25?'DAO ĐỘNG':'TUYỆT VỌNG';$('moraleMood').textContent=mood;
 $('morale').innerHTML=`<div class="morale-top"><span class="morale-label">TINH THẦN TẬP THỂ</span><strong class="morale-value">${s.morale}%</strong></div><div class="meter ${s.morale<35?'danger':''}"><i style="width:${s.morale}%"></i></div><p>${s.morale>=75?'Mọi người tin rằng căn cứ có thể trụ vững. Hiệu suất chiến đấu được tăng cường.':s.morale>=45?'Cư dân vẫn giữ được hy vọng, nhưng kho lương đang khiến mọi người lo lắng.':s.morale>=25?'Bất an lan rộng. Phòng thủ suy giảm khi tinh thần thấp.':'Cư dân tuyệt vọng — nguy cơ bỏ trốn và nổi loạn!'}</p><div class="ration-row"><span>Khẩu phần mỗi người / ngày</span><div class="ration-controls"><button data-ration="-1" ${s.rations<=0?'disabled':''}>−</button><strong>${['Đói','Khắc khổ','Tiêu chuẩn','Dồi dào'][s.rations]}</strong><button data-ration="1" ${s.rations>=3?'disabled':''}>+</button></div></div>`;
 $('feed').innerHTML=s.feed.length?s.feed.map(f=>`<div class="feedline ${f.type}"><span class="feedtime">NGÀY ${f.day}</span><span>${f.text}</span></div>`).join(''):'<div class="feedline">Chưa có báo cáo. Căn cứ đang chờ lệnh của chỉ huy.</div>';
 $('endDay').disabled=s.gameOver;$('endDay').textContent=s.gameOver?'CĂN CỨ ĐÃ THẤT THỦ':'KẾT THÚC NGÀY  →';drawScene();save();
}
function affords(cost){return Object.entries(cost).every(([k,v])=>s[k]>=v)}
function defense(){return Math.min(100,s.fort*16+s.tower*10+s.soldiers.reduce((a,x)=>a+Math.round(x.attack*.8*x.hp/100),0))}
function renderMercs(){let area=$('mercContent');if(s.tab==='roster'){area.innerHTML=`<div class="merc-list">${s.soldiers.length?s.soldiers.map(x=>`<div class="merc"><div class="portrait">${x.icon}</div><div><div class="mercname">${x.name} <span style="color:#9aaa77;font-weight:400">· ${x.role}</span></div><div class="mercmeta">Sinh lực ${x.hp}%</div><div class="mercstats"><span>⚔ ${x.attack} ST</span><span>◎ ${x.aim}% chính xác</span></div></div><span class="eyebrow">ĐANG GÁC</span></div>`).join(''):'<p style="padding:8px;color:#9da99a;font-size:10px">Chưa có lính đánh thuê.</p>'}</div><div class="squad-footer"><span>QUÂN SỐ</span><strong>${s.soldiers.length} / ${s.barracks*4+2}</strong></div>`}else{area.innerHTML=`<div class="merc-list">${hires.map((h,i)=>`<div class="merc"><div class="portrait">${h.icon}</div><div><div class="mercname">${h.name} <span style="color:#9aaa77;font-weight:400">· ${h.role}</span></div><div class="mercmeta">${h.desc}</div><div class="mercstats"><span>⚔ ${h.attack} sát thương</span><span>◎ ${h.aim}%</span></div></div><button class="hirebtn" data-hire="${i}" ${s.actions<=0||!affords(h.cost)||s.soldiers.length>=s.barracks*4+2||s.gameOver?'disabled':''}>MỜI<br>${costText(h.cost)}</button></div>`).join('')}</div><div class="squad-footer"><span>QUÂN SỐ HIỆN TẠI</span><strong>${s.soldiers.length} / ${s.barracks*4+2}</strong></div>`}}

