function drawScene(){const c=$('scene'),ctx=c.getContext('2d');const w=c.width,h=c.height;ctx.clearRect(0,0,w,h);let g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#39433a');g.addColorStop(.52,'#59604a');g.addColorStop(1,'#333a2e');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.fillStyle='#c2b58a';ctx.globalAlpha=.12;for(let i=0;i<18;i++){let x=(i*163+40)%w,y=(i*79+14)%240;ctx.beginPath();ctx.ellipse(x,y,50+(i%4)*19,9+(i%3)*7,0,0,7);ctx.fill()}ctx.globalAlpha=1;
 // distant ruined skyline
 for(let i=0;i<17;i++){let x=i*59-12,hh=40+(i*37%85);ctx.fillStyle=i%2?'#313b33':'#40473a';ctx.fillRect(x,215-hh,34,hh);ctx.fillStyle='#8c8b69';for(let j=0;j<3;j++)ctx.fillRect(x+6+j*9,220-hh+(j%2)*14,4,5);ctx.fillStyle='#242e28';ctx.fillRect(x+29,190-hh,5,hh+25)}
 // ground and winding road
 ctx.fillStyle='#686348';ctx.beginPath();ctx.moveTo(0,325);ctx.lineTo(210,300);ctx.lineTo(380,342);ctx.lineTo(610,307);ctx.lineTo(900,335);ctx.lineTo(900,510);ctx.lineTo(0,510);ctx.fill();ctx.strokeStyle='#8a8060';ctx.lineWidth=2;ctx.setLineDash([12,15]);ctx.beginPath();ctx.moveTo(0,388);ctx.bezierCurveTo(250,349,450,439,900,370);ctx.stroke();ctx.setLineDash([]);
 // scrub / debris
 for(let i=0;i<40;i++){let x=(i*97+21)%w,y=318+(i*43%180);ctx.fillStyle=i%2?'#3b4835':'#51563b';ctx.fillRect(x,y,8+(i%3)*3,3);ctx.fillStyle='#777455';ctx.fillRect(x+4,y-3,3,3)}
 // compound
 const cx=225,cy=251,cw=460,ch=205;ctx.fillStyle='#202920';ctx.fillRect(cx-10,cy-10,cw+20,ch+20);ctx.strokeStyle='#a49a70';ctx.lineWidth=13;ctx.strokeRect(cx,cy,cw,ch);ctx.strokeStyle='#5e6149';ctx.lineWidth=6;ctx.strokeRect(cx,cy,cw,ch);
 // gate
 ctx.fillStyle='#292f25';ctx.fillRect(408,cy+ch-7,92,18);ctx.strokeStyle='#b8aa78';ctx.lineWidth=4;ctx.strokeRect(408,cy+ch-8,92,17);ctx.fillStyle='#a69a6d';ctx.font='bold 11px sans-serif';ctx.fillText('KHU 07',420,cy+ch+26);
 // barracks building
 ctx.fillStyle='#46483a';ctx.fillRect(290,292,104,75);ctx.fillStyle='#7d7655';ctx.beginPath();ctx.moveTo(280,294);ctx.lineTo(340,260);ctx.lineTo(403,294);ctx.fill();ctx.fillStyle='#242d27';ctx.fillRect(307,308,19,23);ctx.fillRect(355,308,19,23);ctx.fillRect(330,337,21,30);ctx.fillStyle='#c5aa63';ctx.fillRect(312,312,9,13);ctx.fillRect(360,312,9,13);
 // command hut
 ctx.fillStyle='#586047';ctx.fillRect(460,307,97,62);ctx.fillStyle='#99916b';ctx.beginPath();ctx.moveTo(450,309);ctx.lineTo(507,278);ctx.lineTo(568,309);ctx.fill();ctx.fillStyle='#272e27';ctx.fillRect(474,322,25,18);ctx.fillRect(517,322,25,18);ctx.fillStyle='#3d2920';ctx.fillRect(500,343,18,26);
 // watchtowers
 const tower=(x,y,n)=>{ctx.fillStyle='#b29760';ctx.fillRect(x-3,y+22,6,47);ctx.strokeStyle='#6e6749';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-3,y+69);ctx.lineTo(x-18,y+82);ctx.moveTo(x+3,y+69);ctx.lineTo(x+18,y+82);ctx.stroke();ctx.fillStyle='#756f50';ctx.fillRect(x-19,y+8,38,19);ctx.fillStyle='#a89864';ctx.fillRect(x-23,y+4,46,6);ctx.fillStyle='#263129';ctx.fillRect(x-13,y+13,26,8);ctx.fillStyle='#cfb777';ctx.fillRect(x+18,y+11,8,3);ctx.fillStyle='#e2d49d';ctx.font='9px sans-serif';ctx.fillText(''+n,x-3,y+23)};
