function loot(type,min,max,risk,place){if(!useAction())return;let amount=rand(min,max);s[type]+=amount;let msg=`Đội tìm kiếm trở về từ ${place}, thu được ${amount} ${type==='scrap'?'sắt vụn':type==='food'?'lương thực':'nhiên liệu'}.`;let r=rand(1,100);if(r<=risk){let harm=rand(1,2);s.people=Math.max(0,s.people-harm);s.morale=Math.max(0,s.morale-8);msg+=` Bị phục kích! Mất ${harm} cư dân.`;log(msg,'alert')}else log(msg,'good');toast(r<=risk?'Chuyến đi gặp phục kích!':`Thu được ${amount} đơn vị.`);if(s.people<=0)lose('Không còn cư dân nào sống sót.');render()}
function startHunt(){if(!useAction())return;let gain=rand(8,15);s.food+=gain;let risk=rand(1,100)<18;if(risk){s.morale=Math.max(0,s.morale-6);log(`Đội săn kiếm được ${gain} khẩu phần nhưng một cư dân bị thương trong lúc rút lui.`,'alert')}else log(`Đội săn mang về ${gain} khẩu phần thực phẩm tươi.`,'good');toast(`Thu được ${gain} lương thực.`);render()}
function repair(){if(s.actions<=0||s.scrap<8)return;spend({scrap:8});useAction();s.wallHP=Math.min(100,(s.wallHP??100)+32);log(`Đội thợ đã gia cố lũy phòng thủ. Độ bền hiện tại ${s.wallHP}%.`,'good');toast('Đã sửa chữa lũy.');render()}
function hire(i){const h=hires[i];if(s.actions<=0||!affords(h.cost)||s.soldiers.length>=s.barracks*4+2)return;spend(h.cost);useAction();s.soldiers.push({name:h.name,role:h.role,hp:h.hp,attack:h.attack,aim:h.aim,icon:h.icon});s.morale=Math.min(100,s.morale+2);log(`${h.name}, ${h.role}, đã gia nhập đội phòng thủ.`,'good');toast(`${h.name} đã nhập ngũ.`);render()}
function upgrade(key){let b=builds.find(x=>x.key===key),level=s[key],cost=Object.fromEntries(Object.entries(b.base).map(([k,v])=>[k,v*level]));if(s.actions<=0||!affords(cost))return;spend(cost);useAction();s[key]++;if(key==='fort')s.wallHP=Math.min(100,(s.wallHP??100)+18);if(key==='barracks')s.morale=Math.min(100,s.morale+4);log(`${b.name} được nâng lên cấp ${s[key]}. ${b.effect(s[key])}.`,'good');toast(`${b.name} đã nâng cấp.`);render()}
function combat(){let zombie=s.day%8===0,threat=28+s.day*5+rand(-6,9)+(zombie?8:0),power=defense()+rand(-7,10)+(s.morale>75?8:0);let who=zombie?'đàn xác sống':'đám cướp';log(`CẢNH BÁO: ${who} tấn công! Sức ép ${threat} · Phòng thủ ${power}.`,'alert');if(power>=threat){let salvage=rand(6,12);s.scrap+=salvage;s.morale=Math.min(100,s.morale+5);s.wallHP=Math.max(30,(s.wallHP??100)-rand(8,18));log(`Đẩy lùi thành công ${who}! Thu hồi ${salvage} sắt vụn. Lũy còn ${s.wallHP}% độ bền.`,'good');toast('PHÒNG THỦ THÀNH CÔNG!')}else{let damage=threat-power;let casualties=Math.min(s.people,damage>30?2:1);s.people-=casualties;s.morale=Math.max(0,s.morale-12);s.wallHP=Math.max(0,(s.wallHP??100)-damage*2);let hurt=s.soldiers.length? s.soldiers[rand(0,s.soldiers.length-1)]:null;if(hurt)hurt.hp=Math.max(15,hurt.hp-rand(10,25));log(`Lũy bị chọc thủng! ${casualties} cư dân thiệt mạng${hurt?`, ${hurt.name} bị thương`:''}. Độ bền lũy ${s.wallHP}%.`,'alert');toast('Căn cứ chịu tổn thất nặng!')};if(s.people<=0)lose('Căn cứ không còn ai để bảo vệ.');}
function endDay(){if(s.gameOver)return;let ration=[.5,.75,1,1.3][s.rations],need=Math.ceil(s.people*ration);if(s.food>=need){s.food-=need;if(s.rations===3)s.morale=Math.min(100,s.morale+3);else if(s.rations===0)s.morale=Math.max(0,s.morale-4);else s.morale=Math.min(100,s.morale+1);log(`Phát ${need} khẩu phần. Cư dân ${s.rations===3?'được ăn no':s.rations===0?'phải chịu đói':'đã nhận khẩu phần'}; tinh thần ${s.morale}%.`,'')}else{let shortage=need-s.food;s.food=0;s.morale=Math.max(0,s.morale-10-shortage);log(`Thiếu ${shortage} khẩu phần! Cư dân đói khát, tinh thần giảm mạnh.`,'alert');if(s.morale<10&&Math.random()<.25&&s.people>2){s.people--;log('Một cư dân bỏ trốn trong đêm.','alert')}}
 // Light passive upkeep and recovery
 if(s.day%3===0&&s.fuel>0){s.fuel--;s.morale=Math.min(100,s.morale+2);log('Máy phát điện hoạt động, giữ ấm khu trú ẩn. Tiêu hao 1 nhiên liệu.','good')}
 if(s.day%4===0){combat();s.lastWave=s.day}
